    Lemma phaseA :
      (forall A1 M1 model1 R1,
          ainv MI A1 M1 model1 -> mstd model1 -> m_fs model1 = m_fs model0 -> m_fds model1 = m_fds model0 ->
          base_ok R1 -> frame M1 -> defined M1 (sp - 32 - DEL_STACK) (32 + DEL_STACK) ->
          eff MI A0 A1 M0 M1 W (umap_foot NS obj1 bl1 bc1 ents1) ->
          lapply (live MI A0) (map (fun e => LDel (fst e)) ents1) (live MI A1) ->
          (forall a, zwin (sp - 32 - DEL_STACK) sp a -> ~ owned MI A1 a) ->
          (forall i, 0 <= i < 40 -> ~ owned MI A1 (obj1 + i)) -> (forall i, 0 <= i < 40 -> ~ owned MI A1 (obj2 + i)) ->
          cell8 SEGS M1 obj1 bl1 -> cell8 SEGS M1 (obj1 + 8) bc1 -> cell8 SEGS M1 (obj1 + 16) 0 ->
          cell8 SEGS M1 (obj1 + 24) 0 -> cell4 SEGS M1 (obj1 + 32) 0x3f800000 -> defined M1 obj1 40 ->
          (bc1 <> 0 -> In (bl1, 8 * bc1) (live MI A1)) ->
          umapx MI NS nval A1 M1 obj2 bl2 bc2 ents2 ->
